export interface Ro3GameData {
  tables: Record<string, Record<string, Record<string, unknown>>>;
  ui: Record<string, unknown>;
}

let cached: Promise<Ro3GameData> | undefined;

export function loadRo3GameData(): Promise<Ro3GameData> {
  if (!cached) {
    cached = (async () => {
      if (typeof window === "undefined" || typeof DecompressionStream === "undefined") {
        throw new Error("RO3 game data must be decompressed in a browser supporting gzip DecompressionStream.");
      }
      const binary = atob(RO3_GAME_DATA_GZIP_BASE64);
      const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
      const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
      const json = await new Response(stream).text();
      const data = JSON.parse(json) as Ro3GameData;
      if (!data.tables || !data.ui) throw new Error("RO3 game-data export is missing required tables or UI metadata.");
      return data;
    })().catch((error) => {
      cached = undefined;
      throw error;
    });
  }
  return cached;
}

export const RO3_GAME_DATA_COMPRESSED_BYTES = 219903;
